const { test, expect } = require('@playwright/test');
const { serverBaseUrl, uniqueRepositoryId, waitForRoute, workbenchBaseUrl } = require('./workbench-test-helpers');

const WORKBENCH_BASE_URL = workbenchBaseUrl();
const SERVER_BASE_URL = serverBaseUrl();
// A query result past 10,000 rows moves to an IndexedDB database of its own, listed in a localStorage registry
// (queryStream.ts); smaller results and ordinary pages stay in the page's memory.
const ROW_STORE_DATABASE_PREFIX = 'rdf4j-workbench-row-store:';
const ROW_STORE_REGISTRY_PREFIX = 'rdf4j.workbench.row-store.v2:';
const ROW_COUNT = 20000;
const SCROLL_ROW_COUNT = 320;
const QUERY_REPOSITORY_ID = uniqueRepositoryId('query-row-lifecycle-query');
const QUERY_REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${QUERY_REPOSITORY_ID}`;
const QUERY_URL = `${WORKBENCH_BASE_URL}/repositories/${QUERY_REPOSITORY_ID}/query`;
const SUMMARY_URL = `${WORKBENCH_BASE_URL}/repositories/${QUERY_REPOSITORY_ID}/summary`;
const SCROLL_REPOSITORY_ID = uniqueRepositoryId('query-row-lifecycle-scroll');
const SCROLL_REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${SCROLL_REPOSITORY_ID}`;
const SCROLL_URL = `${WORKBENCH_BASE_URL}/repositories/${SCROLL_REPOSITORY_ID}/contexts`;
const SCROLL_SUMMARY_URL = `${WORKBENCH_BASE_URL}/repositories/${SCROLL_REPOSITORY_ID}/summary`;
let scrollRepositoryCreated = false;
let queryRepositoryCreated = false;

test.beforeAll(async ({ request }) => {
	const existingQueryRepository = await request.get(QUERY_REPOSITORY_URL);
	if (![400, 404].includes(existingQueryRepository.status())) {
		throw new Error(`Refusing to use non-absent disposable repository ${QUERY_REPOSITORY_ID}: GET ${existingQueryRepository.status()}`);
	}
	const createdQueryRepository = await request.put(QUERY_REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: scrollRepositoryConfiguration(QUERY_REPOSITORY_ID)
	});
	expect([200, 201, 204]).toContain(createdQueryRepository.status());
	queryRepositoryCreated = true;

	const existing = await request.get(SCROLL_REPOSITORY_URL);
	if (![400, 404].includes(existing.status())) {
		throw new Error(`Refusing to use non-absent disposable repository ${SCROLL_REPOSITORY_ID}: GET ${existing.status()}`);
	}
	const created = await request.put(SCROLL_REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: scrollRepositoryConfiguration(SCROLL_REPOSITORY_ID)
	});
	expect([200, 201, 204]).toContain(created.status());
	scrollRepositoryCreated = true;
	const loaded = await request.post(`${SCROLL_REPOSITORY_URL}/statements`, {
		headers: { 'Content-Type': 'application/n-quads' },
		data: Array.from({ length: SCROLL_ROW_COUNT }, (_, index) =>
			`<urn:lifecycle:subject:${index}> <urn:lifecycle:predicate> "row-${index}" <urn:lifecycle:context:${index}> .`).join('\n')
	});
	expect([200, 201, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
	if (queryRepositoryCreated) {
		const deleted = await request.delete(QUERY_REPOSITORY_URL);
		expect([200, 204, 400, 404]).toContain(deleted.status());
		const absent = await request.get(QUERY_REPOSITORY_URL);
		expect([400, 404]).toContain(absent.status());
		console.log(`[query-row-store-query-repository-cleanup] ${JSON.stringify({
			repositoryId: QUERY_REPOSITORY_ID,
			deleteStatus: deleted.status(),
			followupStatus: absent.status(),
			absent: true
		})}`);
	}
	if (scrollRepositoryCreated) {
		const deleted = await request.delete(SCROLL_REPOSITORY_URL);
		expect([200, 204, 400, 404]).toContain(deleted.status());
		const absent = await request.get(SCROLL_REPOSITORY_URL);
		expect([400, 404]).toContain(absent.status());
		console.log(`[query-row-store-disposable-repository-cleanup] ${JSON.stringify({
			repositoryId: SCROLL_REPOSITORY_ID,
			deleteStatus: deleted.status(),
			followupStatus: absent.status(),
			absent: true
		})}`);
	}
});

test('releases batched query rows on reload and page navigation', async ({ page, browserName }, testInfo) => {
	test.skip(browserName === 'firefox', 'Playwright Firefox does not dispatch pagehide to the page that page.reload() replaces');
	test.setTimeout(120000);
	const pageErrors = [];
	const executions = [];
	const responses = [];
	page.on('pageerror', error => recordPageError(pageErrors, error));
	page.on('request', request => {
		if (request.method() === 'POST' && request.url().includes('/query')
				&& (request.headers().accept || '').includes('application/vnd.rdf4j.workbench+ndjson')) {
			executions.push({ url: request.url(), accept: request.headers().accept });
		}
	});
	page.on('response', response => {
		if (response.url().includes('/query')) {
			responses.push({ url: response.url(), status: response.status(), method: response.request().method() });
		}
	});
	await installPageLifecycleRecorder(page);

	await page.goto(SUMMARY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#workbench-app').waitFor({ state: 'visible' });
	const baselineStorage = await readRowStoreSnapshot(page);
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#query-form').waitFor({ state: 'visible' });
	await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
	const firstPageStorage = await readRowStoreSnapshot(page);

	await runBatchedQuery(page);
	const firstActiveStorage = await readRowStoreSnapshot(page);
	const firstExecutionStoreId = assertAddedQueryRows(firstPageStorage, firstActiveStorage, ROW_COUNT);
	const baselineStoreIds = new Set(baselineStorage.storeRecords.map(store => store.id));
	const firstPageOwnedStoreIds = firstActiveStorage.storeRecords
		.filter(store => !baselineStoreIds.has(store.id))
		.map(store => store.id);
	expect(firstPageOwnedStoreIds).toContain(firstExecutionStoreId);
	const firstResult = await visibleQueryResult(page);
	expect(firstResult.status).toMatch(/^20,?000 rows · complete/);
	expect(firstResult.visibleRows).toBeLessThanOrEqual(80);

	await page.reload({ waitUntil: 'domcontentloaded' });
	await page.locator('#query-form').waitFor({ state: 'visible' });
	await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
	const afterReloadLifecycle = await readLifecycleState(page);
	const reloadPageHide = afterReloadLifecycle.pagehide.filter(event => event.path.endsWith('/query')).slice(-1)[0];
	console.log(`[query-row-store-lifecycle-reload] ${JSON.stringify({ reloadPageHide })}`);
	expect(reloadPageHide, 'reload should report whether the prior query document entered BFCache').toBeTruthy();
	let afterReloadStorage;
	if (reloadPageHide.persisted) {
		afterReloadStorage = await readRowStoreSnapshot(page);
		expect(afterReloadStorage.logicalRowCount).toBe(firstActiveStorage.logicalRowCount);
		expect(afterReloadStorage.physicalRowRecordCount).toBe(firstActiveStorage.physicalRowRecordCount);
	} else {
		afterReloadStorage = await waitForExecutionStoreReleased(page, baselineStorage,
			firstPageOwnedStoreIds);
		expect(afterReloadStorage.orphanRowRecordCount).toBe(baselineStorage.orphanRowRecordCount);
		expect(await page.locator('#query-results .query-result-layout').count()).toBe(0);
	}

	await runBatchedQuery(page);
	const secondActiveStorage = await readRowStoreSnapshot(page);
	const secondExecutionStoreId = assertAddedQueryRows(afterReloadStorage, secondActiveStorage, ROW_COUNT);
	const secondResult = await visibleQueryResult(page);
	expect(secondResult.status).toMatch(/^20,?000 rows · complete/);

	await page.goto(SUMMARY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#workbench-app').waitFor({ state: 'visible' });
	const secondPageStoreIds = secondActiveStorage.storeRecords
		.filter(store => !baselineStoreIds.has(store.id))
		.map(store => store.id);
	expect(secondPageStoreIds).toContain(secondExecutionStoreId);
	const afterNavigationLifecycle = await readLifecycleState(page);
	const queryPageHide = afterNavigationLifecycle.pagehide.filter(event => event.path.endsWith('/query')).slice(-1)[0];
	expect(queryPageHide, 'leaving the query page should dispatch pagehide').toBeTruthy();
	const afterNavigationStorage = queryPageHide.persisted
		? await readRowStoreSnapshot(page)
		: await waitForExecutionStoreReleased(page, baselineStorage, secondPageStoreIds);
	if (queryPageHide.persisted) {
		expect(afterNavigationStorage.logicalRowCount).toBe(secondActiveStorage.logicalRowCount);
		expect(afterNavigationStorage.physicalRowRecordCount).toBe(secondActiveStorage.physicalRowRecordCount);
	} else {
		expect(afterNavigationStorage.orphanRowRecordCount).toBe(baselineStorage.orphanRowRecordCount);
	}
	const awayPage = await page.evaluate(() => ({ url: location.href, title: document.title }));

	await page.goBack({ waitUntil: 'domcontentloaded' });
	await page.locator('#query-form').waitFor({ state: 'visible' });
	const returnedPage = await page.evaluate(() => ({
		url: location.href,
		queryResultCount: document.querySelectorAll('#query-results .query-result-layout').length,
		queryResultStatus: document.querySelector('#query-results .query-result-status')
			? document.querySelector('#query-results .query-result-status').textContent.trim() : '',
		busy: document.querySelector('#query-results')
			? document.querySelector('#query-results').getAttribute('aria-busy') : null,
		lifecycle: JSON.parse(sessionStorage.getItem('__rdf4j_query_store_lifecycle_20260928')
			|| '{"pagehide":[],"pageshow":[]}')
	}));
	const backPageShow = returnedPage.lifecycle.pageshow.filter(event => event.path.endsWith('/query')).slice(-1)[0];
	const bfcacheRestored = !!(queryPageHide.persisted && backPageShow && backPageShow.persisted);
	const afterBackStorage = bfcacheRestored
		? await readRowStoreSnapshot(page)
		: await waitForExecutionStoreReleased(page, baselineStorage, secondPageStoreIds);
	if (bfcacheRestored) {
		expect(returnedPage.queryResultCount, 'a BFCache-restored result view must retain its row store').toBe(1);
		expect(returnedPage.queryResultStatus).toMatch(/^20,?000 rows · complete/);
		expect(afterBackStorage.logicalRowCount).toBe(secondActiveStorage.logicalRowCount);
		expect(afterBackStorage.physicalRowRecordCount).toBe(secondActiveStorage.physicalRowRecordCount);
	} else {
		expect(returnedPage.queryResultCount, 'back navigation must not restore the disposed query result view').toBe(0);
		expect(afterBackStorage.storeRecords.some(store => secondPageStoreIds.includes(store.id))).toBe(false);
		expect(afterBackStorage.orphanRowRecordCount).toBe(baselineStorage.orphanRowRecordCount);
	}
	expect(pageErrors).toEqual([]);
	expect(executions).toHaveLength(2);
	expect(executions.every(request => request.accept.includes('application/vnd.rdf4j.workbench+ndjson'))).toBe(true);

	const report = {
		queryUrl: QUERY_URL,
		sequence: ['query 20000 rows with default batch-size=1000000', 'reload',
			'query 20000 rows with default batch-size=1000000',
			'navigate to Summary', 'browser back'],
		bfcachePolicy: 'browser default; no launch flags override back-forward cache',
		baselineStorage,
		firstPageStorage,
		firstActiveStorage,
		afterReloadLifecycle,
		reloadPageHide,
		afterReloadStorage,
		secondActiveStorage,
		afterNavigationStorage,
		afterBackStorage,
		firstResult,
		secondResult,
		awayPage,
		returnedPage,
		queryPageHide,
		backPageShow,
		bfcacheRestored,
		executions,
		responses,
		pageErrors
	};
	console.log(`[query-row-store-lifecycle] ${JSON.stringify(report)}`);
	await testInfo.attach('query-row-store-lifecycle.json', {
		body: Buffer.from(JSON.stringify(report, null, 2)),
		contentType: 'application/json'
	});
});

test('closing the query tab flags its stored result, and cleanup in a fresh same-origin tab deletes it', async ({ page, context, browserName }, testInfo) => {
	test.skip(browserName === 'webkit', 'Playwright WebKit never closes a page closed with runBeforeUnload: true');
	test.setTimeout(120000);
	await installPageLifecycleRecorder(page);
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#query-form').waitFor({ state: 'visible' });
	await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
	const before = await readRowStoreSnapshot(page);
	await runBatchedQuery(page);
	const active = await readRowStoreSnapshot(page);
	const resultStoreId = assertAddedQueryRows(before, active, ROW_COUNT);
	// Close the tab the way a user does: the page's unload handlers (pagehide) run. Playwright's default close
	// skips them unless the page has subframes, which the Query page no longer has (M9.1).
	const closed = page.waitForEvent('close');
	await page.close({ runBeforeUnload: true });
	await closed;

	const recoveryPage = await context.newPage();
	const pageErrors = [];
	recoveryPage.on('pageerror', error => recordPageError(pageErrors, error));
	await recoveryPage.goto(SUMMARY_URL, { waitUntil: 'domcontentloaded' });
	await recoveryPage.locator('#workbench-app').waitFor({ state: 'visible' });
	let after;
	await expect.poll(async () => {
		after = await readRowStoreSnapshot(recoveryPage);
		return after.storeRecords.some(store => store.id === resultStoreId) || resultStoreId in after.registry;
	}, { timeout: 10000, message: 'cleanup deletes the closed tab\'s store and forgets it' }).toBe(false);
	expect(after.orphanRowRecordCount).toBe(0);
	expect(pageErrors).toEqual([]);
	const report = { before, active, resultStoreId, after, pageErrors,
		sequence: ['query 20000 rows with default batch-size=1000000', 'close query tab',
			'open fresh same-origin tab', 'visit Summary'] };
	console.log(`[query-row-store-close-tab] ${JSON.stringify(report)}`);
	await testInfo.attach('query-row-store-close-tab.json', {
		body: Buffer.from(JSON.stringify(report, null, 2)), contentType: 'application/json'
	});
});

test('data-route history return retains or rehydrates worker rows and scroll', async ({ page }, testInfo) => {
	test.setTimeout(120000);
	const pageErrors = [];
	page.on('pageerror', error => recordPageError(pageErrors, error));
	await installPageLifecycleRecorder(page);
	await page.goto(SCROLL_URL, { waitUntil: 'domcontentloaded' });
	const table = page.locator('#contexts-results table[data-workbench-row-table="true"]');
	await table.waitFor({ state: 'visible' });
	await waitForGraphCounts(page);
	expect((await readRowStoreSnapshot(page)).storeRecords, 'a page of 320 rows keeps them in memory').toEqual([]);
	await expect.poll(async () => {
		await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
		return Number(await table.locator('tbody tr[data-workbench-row-index]').first()
			.getAttribute('data-workbench-row-index'));
	}).toBeGreaterThan(200);
	const beforeNavigation = await page.evaluate(() => ({
		url: location.href,
		scrollY: window.scrollY,
		firstRowIndex: Number(document.querySelector('#contexts-results tr[data-workbench-row-index]')
			.getAttribute('data-workbench-row-index')),
		rowCountInDom: document.querySelectorAll('#contexts-results tr[data-workbench-row-index]').length,
		firstRowText: document.querySelector('#contexts-results tr[data-workbench-row-index]')?.textContent.trim() || ''
	}));
	await page.goto(SCROLL_SUMMARY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#workbench-app').waitFor({ state: 'visible' });
	await page.goBack({ waitUntil: 'domcontentloaded' });
	await table.waitFor({ state: 'visible' });
	await waitForGraphCounts(page);
	const returned = await page.evaluate(() => {
		const lifecycle = JSON.parse(sessionStorage.getItem('__rdf4j_query_store_lifecycle_20260928')
			|| '{"pagehide":[],"pageshow":[]}');
		return {
			url: location.href,
			scrollY: window.scrollY,
			firstRowIndex: Number(document.querySelector('#contexts-results tr[data-workbench-row-index]')
				.getAttribute('data-workbench-row-index')),
			rowCountInDom: document.querySelectorAll('#contexts-results tr[data-workbench-row-index]').length,
			firstRowText: document.querySelector('#contexts-results tr[data-workbench-row-index]')?.textContent.trim() || '',
			documentHeight: document.documentElement.scrollHeight,
			scrollRestoration: window.history.scrollRestoration,
			lifecycle
		};
	});
	const leaving = returned.lifecycle.pagehide.filter(event => event.path.endsWith('/contexts')).slice(-1)[0];
	const showing = returned.lifecycle.pageshow.filter(event => event.path.endsWith('/contexts')).slice(-1)[0];
	expect(leaving).toBeTruthy();
	expect(showing).toBeTruthy();
	expect(returned.url).toContain('/contexts');
	const restoredStorage = await readRowStoreSnapshot(page);
	const bfcacheRestored = leaving.persisted === true && showing.persisted === true;
	console.log(`[query-row-store-data-lifecycle] ${JSON.stringify({ beforeNavigation, leaving, showing,
		bfcacheRestored, returned, restoredStorage })}`);
	if (bfcacheRestored) {
		expect(returned.scrollY).toBe(beforeNavigation.scrollY);
		expect(returned.firstRowIndex).toBe(beforeNavigation.firstRowIndex);
		expect(returned.rowCountInDom).toBe(beforeNavigation.rowCountInDom);
		expect(returned.firstRowText).toBe(beforeNavigation.firstRowText);
		await page.evaluate(() => window.scrollBy(0, -160));
		await expect.poll(() => page.locator('#contexts-results tr[data-workbench-row-index]').first()
			.getAttribute('data-workbench-row-index').then(Number)).toBeLessThan(beforeNavigation.firstRowIndex);
	} else {
		expect(leaving.persisted).toBe(false);
		expect(showing.persisted).toBe(false);
		// The position is applied again while the page reaches its final height, a few frames after the rows are bound.
		// The windowed table's height sums measured and estimated row heights, so the returned page can end a pixel
		// shorter than the one that was left when it measured other rows; its bottom is then one pixel higher.
		await expect.poll(async () => Math.abs(await page.evaluate(() => window.scrollY) - beforeNavigation.scrollY), {
			message: 'history navigation should restore the browser-recorded scroll position after route rehydration'
		}).toBeLessThanOrEqual(1);
	}
	expect(restoredStorage.storeRecords, 'the page stores nothing in IndexedDB').toEqual([]);
	expect(pageErrors).toEqual([]);
	const report = { beforeNavigation, returned, leaving, showing, bfcacheRestored,
		restoredStorage, pageErrors,
		sequence: ['scroll data-route table near final rows', 'navigate to Summary',
			'browser Back (actual BFCache or route reload)', 'scroll again'] };
	console.log(`[query-row-store-data-bfcache] ${JSON.stringify(report)}`);
	await testInfo.attach('query-row-store-data-bfcache.json', {
		body: Buffer.from(JSON.stringify(report, null, 2)), contentType: 'application/json'
	});
});

// Plan task M12.1: the same lifecycles when the page changes without loading a document (the router, M8). Leaving a
// route disposes it, which releases its row store; the Query page is kept alive instead (M11.3) and releases its
// result when a newer query runs.

test('leaving a data route in the page releases its rows, and Back rebuilds them at the same rows', async ({ page }) => {
	test.setTimeout(120000);
	const pageErrors = [];
	page.on('pageerror', error => recordPageError(pageErrors, error));
	await installPageLifecycleRecorder(page);
	await page.goto(SCROLL_URL, { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'contexts');
	const table = page.locator('#contexts-results table[data-workbench-row-table="true"]');
	await table.waitFor({ state: 'visible' });
	await waitForGraphCounts(page);
	await expect.poll(async () => {
		await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight / 2));
		return Number(await table.locator('tbody tr[data-workbench-row-index]').first()
			.getAttribute('data-workbench-row-index'));
	}).toBeGreaterThan(100);
	const firstVisibleRow = () => page.evaluate(() => {
		const rows = Array.from(document.querySelectorAll('#contexts-results tr[data-workbench-row-index]'));
		const shown = rows.find(row => row.getBoundingClientRect().top >= 80);
		return shown ? Number(shown.getAttribute('data-workbench-row-index')) : null;
	});
	const left = await firstVisibleRow();
	const documents = [];
	page.on('request', request => {
		if (request.resourceType() === 'document' && request.frame() === page.mainFrame()) {
			documents.push(request.url());
		}
	});

	await page.locator('#navigation').getByRole('link', { name: 'Summary', exact: true }).click();
	await waitForRoute(page, 'summary', { url: SCROLL_SUMMARY_URL });

	await page.goBack();
	await waitForRoute(page, 'contexts', { url: SCROLL_URL });
	await expect.poll(firstVisibleRow).toBe(left);
	expect((await readRowStoreSnapshot(page)).storeRecords, 'a page of 320 rows keeps them in memory').toEqual([]);
	expect(documents, 'the route changes without loading a document').toEqual([]);
	expect((await readLifecycleState(page)).pagehide, 'the document is never hidden').toEqual([]);
	expect(pageErrors).toEqual([]);
});

test('a query result kept while another page is shown is released when a newer query runs', async ({ page }) => {
	test.setTimeout(180000);
	const pageErrors = [];
	page.on('pageerror', error => recordPageError(pageErrors, error));
	await installPageLifecycleRecorder(page);
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'query');
	const before = await readRowStoreSnapshot(page);
	await runBatchedQuery(page);
	const firstStorage = await readRowStoreSnapshot(page);
	const firstStoreId = assertAddedQueryRows(before, firstStorage, ROW_COUNT);

	await page.locator('#navigation').getByRole('link', { name: 'Summary', exact: true }).click();
	await waitForRoute(page, 'summary', { url: SUMMARY_URL });
	expect((await readRowStoreSnapshot(page)).storeRecords.map(store => store.id),
		'the kept Query page keeps its rows').toContain(firstStoreId);
	await page.goBack();
	await waitForRoute(page, 'query', { url: QUERY_URL });
	await expect(page.locator('#query-results .query-result-status')).toHaveText(/^20,?000 rows · complete/);

	await runBatchedQuery(page);
	const secondStorage = await waitForExecutionStoreReleased(page, before, [firstStoreId]);
	assertAddedQueryRows(before, secondStorage, ROW_COUNT);
	expect((await readLifecycleState(page)).pagehide, 'the document is never hidden').toEqual([]);
	expect(pageErrors).toEqual([]);
});

async function runBatchedQuery(page) {
	const values = Array.from({ length: ROW_COUNT }, (_, index) => String(index)).join(' ');
	await page.locator('.CodeMirror').first().evaluate((element, query) => {
		element.CodeMirror.setValue(query);
	}, `SELECT ?item WHERE { VALUES ?item { ${values} } }`);
	await page.locator('#exec').click();
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false', { timeout: 60000 });
	await expect(page.locator('#query-results .query-result-status')).toHaveText(/^20,?000 rows · complete/, { timeout: 15000 });
}

async function visibleQueryResult(page) {
	return page.locator('#query-results').evaluate(root => ({
		status: root.querySelector('.query-result-status')?.textContent?.trim() || '',
		visibleRows: root.querySelectorAll('tbody tr[data-query-row-index]').length,
		resultLayoutCount: root.querySelectorAll('.query-result-layout').length,
		busy: root.getAttribute('aria-busy')
	}));
}

function assertAddedQueryRows(before, after, expectedCount) {
	const beforeIds = new Set(before.storeRecords.map(store => store.id));
	const addedStores = after.storeRecords.filter(store => !beforeIds.has(store.id));
	expect(addedStores, 'one query execution should own one added row store').toHaveLength(1);
	expect(addedStores[0].count).toBe(expectedCount);
	expect(addedStores[0].physicalRecordCount).toBeGreaterThan(0);
	expect(after.logicalRowCount - before.logicalRowCount).toBe(expectedCount);
	expect(after.orphanRowRecordCount).toBe(before.orphanRowRecordCount);
	return addedStores[0].id;
}

async function readRowStoreSnapshot(page) {
	return page.evaluate(async ({ databasePrefix, registryPrefix }) => {
		if (!indexedDB || typeof indexedDB.databases !== 'function') {
			throw new Error('IndexedDB database enumeration is unavailable.');
		}
		// Each stored result is a database of its own. A version-0 entry is what an aborted open leaves in WebKit.
		const names = (await indexedDB.databases())
			.filter(database => database.version > 0 && database.name && database.name.startsWith(databasePrefix))
			.map(database => database.name);
		const storeRecords = [];
		let physicalRowRecordCount = 0;
		let orphanRowRecordCount = 0;
		for (const name of names) {
			const database = await new Promise(resolve => {
				const request = indexedDB.open(name);
				// Deleted since it was listed: do not create it again.
				request.onupgradeneeded = () => request.transaction.abort();
				request.onsuccess = () => resolve(request.result);
				request.onerror = () => resolve(null);
				request.onblocked = () => resolve(null);
			});
			if (!database) {
				continue;
			}
			// The page may delete the store meanwhile: this connection must not hold that up.
			database.onversionchange = () => database.close();
			try {
				if (!database.objectStoreNames.contains('stores') || !database.objectStoreNames.contains('rows')) {
					continue;
				}
				const id = name.substring(databasePrefix.length);
				const counted = await new Promise((resolve, reject) => {
					const transaction = database.transaction(['stores', 'rows'], 'readonly');
					const store = transaction.objectStore('stores').get(id);
					const all = transaction.objectStore('rows').count();
					const owned = transaction.objectStore('rows')
						.count(IDBKeyRange.bound([id, 0], [id, Number.MAX_SAFE_INTEGER]));
					transaction.oncomplete = () => resolve({ store: store.result, all: all.result, owned: owned.result });
					transaction.onerror = transaction.onabort = () => reject(transaction.error
						|| new Error('Unable to inspect query result rows.'));
				});
				physicalRowRecordCount += counted.all;
				if (counted.store) {
					orphanRowRecordCount += counted.all - counted.owned;
					storeRecords.push({ id, count: counted.store.count, format: counted.store.format || null,
						physicalRecordCount: counted.owned });
				} else {
					orphanRowRecordCount += counted.all;
				}
			} finally {
				database.close();
			}
		}
		storeRecords.sort((left, right) => left.id.localeCompare(right.id));
		const registry = {};
		for (let index = 0; index < localStorage.length; index++) {
			const key = localStorage.key(index);
			if (key && key.startsWith(registryPrefix)) {
				registry[key.substring(registryPrefix.length)] = JSON.parse(localStorage.getItem(key));
			}
		}
		return {
			databaseExists: names.length > 0,
			storeRecords,
			logicalRowCount: storeRecords.reduce((sum, store) => sum + store.count, 0),
			physicalRowRecordCount,
			orphanRowRecordCount,
			registry
		};
	}, { databasePrefix: ROW_STORE_DATABASE_PREFIX, registryPrefix: ROW_STORE_REGISTRY_PREFIX });
}

/** Waits until the Graphs page shows every per-graph statement count. */
async function waitForGraphCounts(page) {
	await expect(page.locator('#contexts-results .workbench-count-cell[aria-busy="true"]')).toHaveCount(0);
}

async function waitForExecutionStoreReleased(page, baseline, storeIds) {
	let latestSnapshot;
	await expect.poll(async () => {
		const current = await readRowStoreSnapshot(page);
		latestSnapshot = current;
		const retainedExecutionStores = current.storeRecords.filter(store => storeIds.includes(store.id));
		return {
			retainedStoreIds: retainedExecutionStores.map(store => store.id),
			orphanRowRecordCount: current.orphanRowRecordCount
		};
	}, { timeout: 10000 }).toEqual({
		retainedStoreIds: [],
		orphanRowRecordCount: baseline.orphanRowRecordCount
	});
	return latestSnapshot;
}

async function readLifecycleState(page) {
	return page.evaluate(() => JSON.parse(sessionStorage.getItem('__rdf4j_query_store_lifecycle_20260928')
		|| '{"pagehide":[],"pageshow":[]}'));
}

/**
 * Records an uncaught page error. A ResizeObserver loop notice is the browser reporting that layout settled over more
 * than one frame (WebKit raises it as an error event); it is not a failure of the page.
 */
function recordPageError(pageErrors, error) {
	if (!/^ResizeObserver loop/.test(error.message)) {
		pageErrors.push(error.message);
	}
}

async function installPageLifecycleRecorder(page) {
	await page.addInitScript(() => {
		const key = '__rdf4j_query_store_lifecycle_20260928';
		const read = () => {
			try {
				return JSON.parse(sessionStorage.getItem(key) || '{"pagehide":[],"pageshow":[]}');
			} catch (error) {
				return { pagehide: [], pageshow: [] };
			}
		};
		window.addEventListener('pagehide', event => {
			const state = read();
			state.pagehide.push({ persisted: event.persisted, path: location.pathname });
			sessionStorage.setItem(key, JSON.stringify(state));
		});
		window.addEventListener('pageshow', event => {
			const state = read();
			state.pageshow.push({ persisted: event.persisted, path: location.pathname });
			sessionStorage.setItem(key, JSON.stringify(state));
		});
	});
}

function scrollRepositoryConfiguration(repositoryId) {
	return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ; config:rep.id "${repositoryId}" ; rdfs:label "Workbench row lifecycle scroll fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ] ].`;
}
